import { Affiliate, Lead, LeadStatus } from '../types';
import { MOCK_AFFILIATES, MOCK_LEADS } from '../constants';

const AFFILIATES_KEY = 'ib_affiliates';
const LEADS_KEY = 'ib_leads';

export const db = {
  init: () => {
    if (!localStorage.getItem(AFFILIATES_KEY)) {
      localStorage.setItem(AFFILIATES_KEY, JSON.stringify(MOCK_AFFILIATES));
    }
    if (!localStorage.getItem(LEADS_KEY)) {
      localStorage.setItem(LEADS_KEY, JSON.stringify(MOCK_LEADS));
    }
  },

  getAffiliateBySlug: (slug: string): Affiliate | undefined => {
    const apps = JSON.parse(localStorage.getItem(AFFILIATES_KEY) || '[]');
    return apps.find((a: Affiliate) => a.slug === slug);
  },

  getAffiliateById: (id: string): Affiliate | undefined => {
    const apps = JSON.parse(localStorage.getItem(AFFILIATES_KEY) || '[]');
    return apps.find((a: Affiliate) => a.id === id);
  },

  getLeadsForAffiliate: (affiliateId: string): Lead[] => {
    const leads = JSON.parse(localStorage.getItem(LEADS_KEY) || '[]');
    return leads.filter((l: Lead) => l.affiliateId === affiliateId);
  },

  addLead: (lead: Omit<Lead, 'id' | 'status' | 'createdAt'>) => {
    const leads = JSON.parse(localStorage.getItem(LEADS_KEY) || '[]');
    const newLead: Lead = {
      ...lead,
      id: Math.random().toString(36).substr(2, 9),
      status: LeadStatus.RECEIVED,
      createdAt: new Date().toISOString()
    };
    leads.push(newLead);
    localStorage.setItem(LEADS_KEY, JSON.stringify(leads));
    return newLead;
  }
};

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { db } from '../services/db';
