import { Affiliate, NicheType } from '../types';
import { Input, Button } from '../components/UI';

const LandingPage: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const [affiliate, setAffiliate] = useState<Affiliate | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitted, setSubmitted] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });

  useEffect(() => {
    db.init();
    const found = db.getAffiliateBySlug(slug || '');
    setAffiliate(found || null);
    setLoading(false);
  }, [slug]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!affiliate) return;

    db.addLead({
      affiliateId: affiliate.id,
      name: formData.name,
      email: formData.email,
      phone: formData.phone,
    });
    setSubmitted(true);
  };

  if (loading) return <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">Loading...</div>;

  // Use generic data if no affiliate found (acting as home page)
  const effectiveAffiliate = affiliate || {
    name: 'The Official',
    niche: NicheType.GENERAL,
  };

  const bgImage = NICHE_IMAGES[effectiveAffiliate.niche as NicheType] || NICHE_IMAGES[NicheType.GENERAL];

  return (
    <div className="relative min-h-screen bg-[#0a0a0a] overflow-hidden">
      {/* Dynamic Background Image with Overlay */}
      <div 
        className="absolute inset-0 z-0 bg-cover bg-center transition-all duration-1000"
        style={{ backgroundImage: `url(${bgImage})` }}
      >
        <div className="absolute inset-0 bg-gradient-to-b from-[#0a0a0a]/80 via-[#0a0a0a]/90 to-[#0a0a0a]"></div>
      </div>

      {/* Navigation */}
      <header className="relative z-10 container mx-auto px-6 py-8 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-[#FFD700] rounded-lg flex items-center justify-center">
            <svg className="w-6 h-6 text-black" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L3 7v9c0 5.25 3.75 10.16 9 11.5 5.25-1.34 9-6.25 9-11.5V7l-9-5z"/></svg>
          </div>
          <div>
            <h1 className="text-xl font-bold uppercase tracking-tight">The Insurance Boss</h1>
            <p className="text-[10px] text-zinc-400 font-semibold uppercase tracking-[0.2em]">Policy Review Authority</p>
          </div>
        </div>
        <div className="flex items-center gap-6">
          <Link to="/login" className="text-sm font-semibold text-zinc-400 hover:text-white transition-colors">Staff Access</Link>
          <Button>Get A Quote</Button>
        </div>
      </header>

      {/* Hero Content */}
      <main className="relative z-10 container mx-auto px-6 pt-20 pb-32 flex flex-col items-center text-center">
        <div className="max-w-4xl">
          <h2 className="text-5xl md:text-7xl font-extrabold mb-6 leading-tight">
            Is Your Policy <br />
            <span className="text-[#FFD700]">Protecting You?</span>
          </h2>
          <p className="text-xl text-zinc-300 mb-4 max-w-2xl mx-auto">
            Exclusive Insurance Access for <span className="text-white font-bold">{effectiveAffiliate.name}'s</span> Network.
          </p>
          <p className="text-zinc-500 mb-12">
            Upload your policy for an instant technical audit. Identify traps before they identify you.
          </p>

          {/* Lead Capture Form */}
          <div className="bg-[#121212]/50 backdrop-blur-xl border border-zinc-800 p-8 rounded-[2.5rem] w-full max-w-2xl mx-auto shadow-2xl">
            {submitted ? (
              <div className="py-12 flex flex-col items-center gap-4">
                <div className="w-16 h-16 bg-emerald-500/20 text-emerald-500 rounded-full flex items-center justify-center">
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"/></svg>
                </div>
                <h3 className="text-2xl font-bold">Inquiry Received</h3>
                <p className="text-zinc-400">The Boss is reviewing your request. Stand by for contact.</p>
                <Button variant="secondary" onClick={() => setSubmitted(false)} className="mt-4">Submit Another</Button>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="flex flex-col gap-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <Input 
                    label="Full Name" 
                    placeholder="Enter your name" 
                    required 
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                  />
                  <Input 
                    label="Email Address" 
                    type="email" 
                    placeholder="boss@example.com" 
                    required 
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                  />
                </div>
                <Input 
                  label="Phone Number" 
                  type="tel" 
                  placeholder="(555) 000-0000" 
                  required 
                  value={formData.phone}
                  onChange={e => setFormData({...formData, phone: e.target.value})}
