export default LandingPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../services/db';
import { Affiliate, Lead } from '../types';
import { Button, Card, Badge, Input } from '../components/UI';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [affiliate, setAffiliate] = useState<Affiliate | null>(null);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const session = localStorage.getItem('ib_session');
    if (!session) {
      navigate('/login');
      return;
    }

    const user = JSON.parse(session);
    setAffiliate(user);
    setLeads(db.getLeadsForAffiliate(user.id));
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('ib_session');
    navigate('/login');
  };

  const copyRefLink = () => {
    const link = `${window.location.origin}/#/${affiliate?.slug}`;
    navigator.clipboard.writeText(link);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (!affiliate) return null;

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white">
      {/* Sidebar-style Nav (Top for mobile compatibility) */}
      <nav className="border-b border-zinc-800 bg-[#121212] sticky top-0 z-50">
        <div className="container mx-auto px-6 h-20 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-[#FFD700] rounded flex items-center justify-center">
              <svg className="w-5 h-5 text-black" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L3 7v9c0 5.25 3.75 10.16 9 11.5 5.25-1.34 9-6.25 9-11.5V7l-9-5z"/></svg>
            </div>
            <span className="font-bold text-lg">THE VAULT</span>
          </div>
          <div className="flex items-center gap-6">
            <div className="text-right hidden sm:block">
              <p className="text-xs text-zinc-500 uppercase font-bold tracking-widest">Affiliate</p>
              <p className="text-sm font-semibold">{affiliate.name}</p>
            </div>
            <Button variant="secondary" onClick={handleLogout} className="px-4 py-2">Sign Out</Button>
          </div>
        </div>
      </nav>

      <main className="container mx-auto px-6 py-12">
        {/* Welcome Section */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-12 gap-6">
          <div>
            <h2 className="text-4xl font-extrabold mb-2">Welcome Back, Agent</h2>
            <p className="text-zinc-500">Track your performance and manage incoming insurance leads.</p>
          </div>
          <div className="flex flex-col gap-2 w-full md:w-auto">
            <label className="text-xs font-bold text-zinc-500 uppercase tracking-tighter">Your Unique Referral Link</label>
            <div className="flex gap-2">
              <div className="bg-[#121212] border border-zinc-800 rounded-xl px-4 py-2 text-sm text-zinc-400 font-mono overflow-hidden whitespace-nowrap max-w-[200px] md:max-w-xs">
                {`${window.location.origin}/#/${affiliate.slug}`}
              </div>
              <Button onClick={copyRefLink} className="py-2 px-4 whitespace-nowrap">
                {copied ? 'Copied!' : 'Copy Link'}
              </Button>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
          <Card className="p-6">
            <p className="text-zinc-500 text-xs font-bold uppercase mb-1">Total Leads</p>
            <p className="text-4xl font-extrabold">{leads.length}</p>
          </Card>
          <Card className="p-6">
            <p className="text-[#FFD700] text-xs font-bold uppercase mb-1">Closed Deals</p>
            <p className="text-4xl font-extrabold">{leads.filter(l => l.status === 'Closed').length}</p>
          </Card>
          <Card className="p-6">
            <p className="text-zinc-500 text-xs font-bold uppercase mb-1">Conversion Rate</p>
            <p className="text-4xl font-extrabold">
              {leads.length > 0 ? Math.round((leads.filter(l => l.status === 'Closed').length / leads.length) * 100) : 0}%
            </p>
          </Card>
        </div>

        {/* Lead Table */}
        <div>
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-bold">Generated Leads</h3>
            <div className="flex items-center gap-2">
               <span className="text-sm text-zinc-500">Filtered by: <span className="text-white">Active</span></span>
            </div>
          </div>
          <Card className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b border-zinc-800 bg-white/5">
                  <th className="px-6 py-4 text-xs font-bold text-zinc-500 uppercase">Date</th>
                  <th className="px-6 py-4 text-xs font-bold text-zinc-500 uppercase">Name</th>
                  <th className="px-6 py-4 text-xs font-bold text-zinc-500 uppercase">Contact</th>
                  <th className="px-6 py-4 text-xs font-bold text-zinc-500 uppercase">Status</th>
                  <th className="px-6 py-4 text-xs font-bold text-zinc-500 uppercase">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800">
                {leads.length > 0 ? leads.map(lead => (
                  <tr key={lead.id} className="hover:bg-white/5 transition-colors">
                    <td className="px-6 py-4 text-sm text-zinc-400">
                      {new Date(lead.createdAt).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 font-semibold">{lead.name}</td>
                    <td className="px-6 py-4">
                      <div className="text-sm">{lead.email}</div>
                      <div className="text-xs text-zinc-500">{lead.phone}</div>
                    </td>
                    <td className="px-6 py-4">
                      <Badge status={lead.status} />
                    </td>
                    <td className="px-6 py-4">
                      <button className="text-zinc-400 hover:text-[#FFD700] text-sm font-semibold underline underline-offset-4">Details</button>
                    </td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan={5} className="px-6 py-20 text-center text-zinc-600 italic">
                      No leads captured yet. Share your link to start generating!
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </Card>
        </div>
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { db } from '../services/db';
import { Input, Button, Card } from '../components/UI';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    db.init();
    // Simple mock logic: any mock email works, otherwise use 'sarah@theboss.com'
    const affiliates = JSON.parse(localStorage.getItem('ib_affiliates') || '[]');
    const user = affiliates.find((a: any) => a.email === email);

    if (user) {
      localStorage.setItem('ib_session', JSON.stringify(user));
      navigate('/vault');
    } else {
      setError('Affiliate credentials not found in Boss database.');
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center px-6 py-12">
      <div className="w-full max-w-md">
        <div className="text-center mb-10">
          <Link to="/" className="inline-flex items-center gap-3 mb-8">
            <div className="w-12 h-12 bg-[#FFD700] rounded-xl flex items-center justify-center">
              <svg className="w-8 h-8 text-black" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L3 7v9c0 5.25 3.75 10.16 9 11.5 5.25-1.34 9-6.25 9-11.5V7l-9-5z"/></svg>
            </div>
          </Link>
          <h1 className="text-3xl font-extrabold mb-2 uppercase tracking-tight">Access The Vault</h1>
          <p className="text-zinc-500">Authorized Affiliate Access Only</p>
        </div>

        <Card className="p-8 shadow-2xl">
          <form onSubmit={handleLogin} className="flex flex-col gap-6">
            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-3 rounded-lg text-sm text-center">
                {error}
              </div>
            )}
            <Input 
              label="Affiliate Email" 
              type="email" 
              placeholder="boss@theboss.com" 
              required
              value={email}
              onChange={e => setEmail(e.target.value)}
            />
            <div className="flex flex-col gap-2">
              <Input label="Access Key" type="password" placeholder="••••••••" required />
              <button type="button" className="text-xs text-zinc-500 hover:text-[#FFD700] self-end transition-colors">Request Reset</button>
            </div>
            <Button type="submit" fullWidth className="py-4 text-lg">Initialize Connection</Button>

            <div className="text-center">
               <p className="text-xs text-zinc-600 uppercase tracking-widest font-bold">Try: sarah@theboss.com</p>
            </div>
          </form>
        </Card>

        <p className="text-center mt-8 text-zinc-500 text-sm">
          Don't have an affiliate account? <br />
          <a href="#" className="text-[#FFD700] font-bold hover:underline">Apply to the Boss Network</a>
        </p>
      </div>
    </div>
  );
};

