export const MultiStepForm: React.FC<{ affiliateId: string; onSuccess: () => void }> = ({ affiliateId, onSuccess }) => {
  const [step, setStep] = useState(1);
  const totalSteps = 8;
  const progress = Math.round((step / totalSteps) * 100);

  const [formData, setFormData] = useState({
    businessName: '',
    dba: '',
    fein: '',
    yearsInBusiness: '',
    address: '',
    address2: '',
    city: '',
    state: '',
    zip: '',
    country: 'United States',
    businessTypes: [] as string[],
    hasActiveCoverage: false,
    knowsPremium: false,
    hasDeclarations: false,
    contactName: '',
    email: '',
    phone: '',
  });

  const nextStep = () => setStep(s => Math.min(s + 1, totalSteps));
  const prevStep = () => setStep(s => Math.max(s - 1, 1));

  const toggleBusinessType = (type: string) => {
    setFormData(prev => ({
      ...prev,
      businessTypes: prev.businessTypes.includes(type)
        ? prev.businessTypes.filter(t => t !== type)
        : [...prev.businessTypes, type]
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    db.addLead(affiliateId, formData.contactName, formData.email, formData.phone, {
      businessName: formData.businessName,
      dba: formData.dba,
      fein: formData.fein,
      yearsInBusiness: formData.yearsInBusiness,
      address: formData.address,
      city: formData.city,
      state: formData.state,
      zipCode: formData.zip,
      businessTypes: formData.businessTypes,
      hasActiveCoverage: formData.hasActiveCoverage,
      knowsPremium: formData.knowsPremium,
      hasDeclarations: formData.hasDeclarations,
    });
    onSuccess();
  };

  const renderStep = () => {
    switch(step) {
      case 1:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Company Identity</h2>
            <div className="space-y-4">
              <FormInput label="Business Legal Name *" value={formData.businessName} onChange={v => setFormData({...formData, businessName: v})} placeholder="Legal Entity Name" />
              <FormInput label="DBA (Doing Business As)" value={formData.dba} onChange={v => setFormData({...formData, dba: v})} placeholder="Trade Name" />
              <div className="grid grid-cols-2 gap-4">
                <FormInput label="Federal EIN *" value={formData.fein} onChange={v => setFormData({...formData, fein: v})} placeholder="XX-XXXXXXX" />
                <FormInput label="Years Active *" value={formData.yearsInBusiness} onChange={v => setFormData({...formData, yearsInBusiness: v})} placeholder="Age of Business" />
              </div>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Headquarters</h2>
            <div className="space-y-4">
              <FormInput label="HQ Address *" value={formData.address} onChange={v => setFormData({...formData, address: v})} placeholder="..." />
              <FormInput label="City *" value={formData.city} onChange={v => setFormData({...formData, city: v})} placeholder="..." />
              <div className="grid grid-cols-2 gap-4">
                <FormInput label="State *" value={formData.state} onChange={v => setFormData({...formData, state: v})} placeholder="..." />
                <FormInput label="Zip Code *" value={formData.zip} onChange={v => setFormData({...formData, zip: v})} placeholder="..." />
              </div>
            </div>
          </div>
        );
      case 3:
        const industries = ["Logistics & Fleet", "Tech & Cyber", "Manufacturing", "Medical & Pharma", "Professional Services", "Real Estate Dev", "Hospitality", "Wholesale", "Agriculture", "Construction", "Auto Dealership", "Food & Beverage", "Retail", "Other"];
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Commercial Industry</h2>
            <div className="grid grid-cols-2 gap-3 max-h-[300px] overflow-y-auto pr-2 no-scrollbar">
              {industries.map(ind => (
                <button 
                  key={ind}
                  type="button"
                  onClick={() => toggleBusinessType(ind)}
                  className={`px-4 py-3 rounded-xl text-xs font-black border transition-all ${formData.businessTypes.includes(ind) ? 'bg-[#EAB308] text-black border-[#EAB308]' : 'bg-white/5 border-white/10 text-gray-500 hover:bg-white/10'}`}
                >
                  {ind}
                </button>
              ))}
            </div>
          </div>
        );
      case 5:
        return (
          <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-4xl font-black tracking-tighter mb-8 text-white">Policy Profile</h2>
            <ToggleQuestion label="Active GL/WC Coverage?" value={formData.hasActiveCoverage} onChange={v => setFormData({...formData, hasActiveCoverage: v})} />
            <ToggleQuestion label="Know Monthly Premium?" value={formData.knowsPremium} onChange={v => setFormData({...formData, knowsPremium: v})} />
            <ToggleQuestion label="Declarations Ready?" value={formData.hasDeclarations} onChange={v => setFormData({...formData, hasDeclarations: v})} />
          </div>
        );
      case 7:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Authorized Contact</h2>
            <div className="space-y-4">
              <FormInput label="Decision Maker Name *" value={formData.contactName} onChange={v => setFormData({...formData, contactName: v})} placeholder="..." />
              <FormInput label="Work Email *" type="email" value={formData.email} onChange={v => setFormData({...formData, email: v})} placeholder="..." />
              <FormInput label="Direct Line *" type="tel" value={formData.phone} onChange={v => setFormData({...formData, phone: v})} placeholder="..." />
            </div>
          </div>
        );
      case 8:
        return (
          <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Final Authorization</h2>
            <div className="bg-white/5 border border-white/10 rounded-2xl p-6 space-y-4">
              <div className="flex justify-between border-b border-white/5 pb-2">
                <span className="text-gray-400 text-xs font-bold tracking-widest">Entity</span>
                <span className="font-bold text-white uppercase">{formData.businessName}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2">
                <span className="text-gray-400 text-xs font-bold tracking-widest">Authorized Rep</span>
                <span className="font-bold text-white">{formData.contactName}</span>
              </div>
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="w-full">
      <div className="mb-4 space-y-2">
        <div className="flex justify-between items-end">
          <span className="text-[#EAB308] text-[9px] font-black tracking-[0.2em]">Step {step} of {totalSteps}</span>
          <span className="text-white text-xl font-black">{progress}%</span>
        </div>
        <div className="h-1 bg-white/10 rounded-full overflow-hidden">
          <div className="h-full bg-[#EAB308] transition-all duration-500 shadow-[0_0_10px_rgba(234,179,8,0.5)]" style={{ width: `${progress}%` }} />
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-[#111] border border-white/10 rounded-[32px] p-8 shadow-2xl min-h-[500px] flex flex-col">
        <div className="flex-grow">
          {renderStep()}
        </div>
        <div className="mt-8 flex gap-4">
          {step > 1 && (
            <button type="button" onClick={prevStep} className="px-6 py-4 rounded-2xl bg-white/5 border border-white/10 font-black text-xs tracking-widest text-gray-400 hover:bg-white/10 transition-all">Back</button>
          )}
          {step < totalSteps ? (
            <button type="button" onClick={() => {
               if (step === 3) setStep(5);
               else if (step === 5) setStep(7);
               else if (step === 7) setStep(8);
               else nextStep();
            }} className="flex-1 px-6 py-4 rounded-2xl bg-[#EAB308] text-black font-black text-xs tracking-[0.2em] hover:scale-[1.01] active:scale-95 transition-all">Continue</button>
          ) : (
            <button type="submit" className="flex-1 px-6 py-4 rounded-2xl bg-[#EAB308] text-black font-black text-xs tracking-[0.2em] hover:scale-[1.01] active:scale-95 transition-all">Initialize Desk</button>
          )}
        </div>
      </form>
    </div>
  );
};

export const FormInput = ({ label, ...props }: any) => (
  <div className="space-y-1">
    <label className="block text-[9px] font-black text-[#EAB308] tracking-widest">{label}</label>
    <input 
      {...props}
      className="w-full bg-black border border-white/5 rounded-xl px-4 py-3 focus:outline-none focus:border-[#EAB308] transition-all font-bold text-white placeholder:text-gray-500"
      onChange={e => props.onChange?.(e.target.value)}
    />
  </div>
);

export const ToggleQuestion = ({ label, value, onChange }: any) => (
  <div className="bg-black/40 border border-white/5 rounded-xl p-4 flex justify-between items-center gap-4 hover:border-white/20 transition-all">
    <span className="font-black text-gray-200 text-[10px] tracking-wider">{label}</span>
    <div className="flex bg-black p-1 rounded-lg">
      <button type="button" onClick={() => onChange(true)} className={`px-4 py-1 rounded text-[10px] font-black transition-all ${value ? 'bg-[#EAB308] text-black shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>Yes</button>
      <button type="button" onClick={() => onChange(false)} className={`px-4 py-1 rounded text-[10px] font-black transition-all ${!value ? 'bg-[#EAB308] text-black shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>No</button>
    </div>
  </div>
);

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { db } from '../services/dbService';
import { Affiliate, Lead, LeadStatus, PartnerApplication, LandingPageRequest } from '../types';
import { Button } from './Button';
import { MultiStepForm, FormInput } from './LandingPage';
import { PromotionPage } from './PromotionPage';

interface DashboardProps {
  user: Affiliate;
  onLogout: () => void;
}

type Tab = 'overview' | 'leads' | 'applications' | 'lead_management' | 'landing_requests' | 'payouts' | 'tools' | 'program' | 'affiliate_manager' | 'recycle_bin';

export const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [globalLeads, setGlobalLeads] = useState<Lead[]>([]);
  const [applications, setApplications] = useState<PartnerApplication[]>([]);
  const [landingRequests, setLandingRequests] = useState<LandingPageRequest[]>([]);
  const [affiliates, setAffiliates] = useState<Affiliate[]>([]);

  const [deletedLeads, setDeletedLeads] = useState<Lead[]>([]);
  const [deletedApps, setDeletedApps] = useState<PartnerApplication[]>([]);
  const [deletedLandingReqs, setDeletedLandingReqs] = useState<LandingPageRequest[]>([]);
  const [deletedAffiliates, setDeletedAffiliates] = useState<Affiliate[]>([]);

  const [activeTab, setActiveTab] = useState<Tab>(user.role === 'admin' ? 'applications' : 'overview');
  const [copySuccess, setCopySuccess] = useState(false);
  const [formSubmitted, setFormSubmitted] = useState(false);
  const [selectedAsset, setSelectedAsset] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Customization form state
  const [customNiche, setCustomNiche] = useState('Commercial Logistics');
  const [customNotes, setCustomNotes] = useState('');

  // User Manager state
  const [newUser, setNewUser] = useState({
    name: '',
    email: '',
    username: '',
    password: '',
    role: 'partner' as 'partner' | 'admin'
  });

  const baseUrl = window.location.origin;
  const referralLink = `${baseUrl}/#/${user.slug}`;

  const updateData = useCallback(() => {
    if (user.role === 'admin') {
      const allApps = db.getApplications(true);
      const allLand = db.getLandingPageRequests(true);
      const allAff = db.getAffiliates(true);
      const allLeads = db.getGlobalLeads(true);

      setApplications(allApps.filter(a => !a.isDeleted));
      setLandingRequests(allLand.filter(r => !r.isDeleted));
      setAffiliates(allAff.filter(a => !a.isDeleted));
      setGlobalLeads(allLeads.filter(l => !l.isDeleted));

      setDeletedApps(allApps.filter(a => a.isDeleted));
      setDeletedLandingReqs(allLand.filter(r => r.isDeleted));
      setDeletedAffiliates(allAff.filter(a => a.isDeleted));
      setDeletedLeads(allLeads.filter(l => l.isDeleted));
    } else {
      const allLeads = db.getLeadsForAffiliate(user.id, true);
      setLeads(allLeads.filter(l => !l.isDeleted));
      setDeletedLeads(allLeads.filter(l => l.isDeleted));
    }
  }, [user.id, user.role]);

  useEffect(() => {
    updateData();
    const interval = setInterval(updateData, 5000);
    return () => clearInterval(interval);
  }, [updateData]);

  const copyToClipboard = async (text: string = referralLink) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error('Failed to copy link:', err);
    }
  };

  const handleCustomizationSubmit = () => {
    db.submitLandingPageRequest({
      affiliateId: user.id,
      affiliateName: user.name,
      niche: customNiche,
      notes: customNotes
    });
    setSelectedAsset(null);
    setCustomNotes('');
    alert('Commercial Vault Customization Logged!');
    updateData();
  };

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();
    db.createAffiliate(newUser);
    updateData();
    setNewUser({ name: '', email: '', username: '', password: '', role: 'partner' });
    alert('Commercial Partner Provisioned Successfully.');
  };

  const handleDelete = (type: 'lead' | 'application' | 'landing_request' | 'affiliate', id: string) => {
    if(confirm('Move this entry to the Recycling Bin?')) {
      db.deleteEntry(type, id);
      updateData();
    }
  };

  const handleRestore = (type: 'lead' | 'application' | 'landing_request' | 'affiliate', id: string) => {
    db.restoreEntry(type, id);
    alert('Entry restored to active database.');
    updateData();
  };

  const handlePurge = (type: 'lead' | 'application' | 'landing_request' | 'affiliate', id: string) => {
    if(confirm('Permanent action: This will be deleted from the vault forever. Purge now?')) {
      db.purgeEntry(type, id);
      updateData();
    }
  };

