    db.updateLeadStatus(leadId, status);
    updateData();
  };

  const handleExportVault = () => {
    const data = db.exportVault();
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `InsuranceBoss_Commercial_Vault_Backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImportVault = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      const success = db.importVault(content);
      if (success) {
        alert("Commercial Vault Re-Synchronized Successfully. Reloading...");
        window.location.reload();
      } else {
        alert("Error: Invalid Vault Data Package.");
      }
    };
    reader.readAsText(file);
  };

