  const progress = Math.round((step / totalSteps) * 100);

  const [formData, setFormData] = useState({
    businessName: '',
    dba: '',
    fein: '',
    yearsInBusiness: '',
    address: '',
    address2: '',
    city: '',
    state: '',
    zip: '',
    country: 'United States',
