import { Button } from './Button';
import { MultiStepForm, FormInput } from './LandingPage';
import { PromotionPage } from './PromotionPage';

interface DashboardProps {
  user: Affiliate;
  onLogout: () => void;
}

type Tab = 'overview' | 'leads' | 'applications' | 'lead_management' | 'landing_requests' | 'payouts' | 'tools' | 'program' | 'affiliate_manager' | 'recycle_bin';

export const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [globalLeads, setGlobalLeads] = useState<Lead[]>([]);
  const [applications, setApplications] = useState<PartnerApplication[]>([]);
  const [landingRequests, setLandingRequests] = useState<LandingPageRequest[]>([]);
  const [affiliates, setAffiliates] = useState<Affiliate[]>([]);

  const [deletedLeads, setDeletedLeads] = useState<Lead[]>([]);
  const [deletedApps, setDeletedApps] = useState<PartnerApplication[]>([]);
  const [deletedLandingReqs, setDeletedLandingReqs] = useState<LandingPageRequest[]>([]);
  const [deletedAffiliates, setDeletedAffiliates] = useState<Affiliate[]>([]);

  const [activeTab, setActiveTab] = useState<Tab>(user.role === 'admin' ? 'applications' : 'overview');
  const [copySuccess, setCopySuccess] = useState(false);
  const [formSubmitted, setFormSubmitted] = useState(false);
  const [selectedAsset, setSelectedAsset] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Customization form state
  const [customNiche, setCustomNiche] = useState('Commercial Logistics');
  const [customNotes, setCustomNotes] = useState('');

  // User Manager state
  const [newUser, setNewUser] = useState({
    name: '',
    email: '',
    username: '',
    password: '',
    role: 'partner' as 'partner' | 'admin'
  });

  const baseUrl = window.location.origin;
  const referralLink = `${baseUrl}/#/${user.slug}`;

  const updateData = useCallback(() => {
    if (user.role === 'admin') {
      const allApps = db.getApplications(true);
      const allLand = db.getLandingPageRequests(true);
      const allAff = db.getAffiliates(true);
      const allLeads = db.getGlobalLeads(true);

      setApplications(allApps.filter(a => !a.isDeleted));
      setLandingRequests(allLand.filter(r => !r.isDeleted));
      setAffiliates(allAff.filter(a => !a.isDeleted));
      setGlobalLeads(allLeads.filter(l => !l.isDeleted));

      setDeletedApps(allApps.filter(a => a.isDeleted));
      setDeletedLandingReqs(allLand.filter(r => r.isDeleted));
      setDeletedAffiliates(allAff.filter(a => a.isDeleted));
      setDeletedLeads(allLeads.filter(l => l.isDeleted));
    } else {
      const allLeads = db.getLeadsForAffiliate(user.id, true);
      setLeads(allLeads.filter(l => !l.isDeleted));
      setDeletedLeads(allLeads.filter(l => l.isDeleted));
    }
  }, [user.id, user.role]);

  useEffect(() => {
    updateData();
    const interval = setInterval(updateData, 5000);
    return () => clearInterval(interval);
  }, [updateData]);

  const copyToClipboard = async (text: string = referralLink) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error('Failed to copy link:', err);
    }
  };

  const handleCustomizationSubmit = () => {
    db.submitLandingPageRequest({
      affiliateId: user.id,
      affiliateName: user.name,
      niche: customNiche,
      notes: customNotes
    });
    setSelectedAsset(null);
    setCustomNotes('');
    alert('Commercial Vault Customization Logged!');
    updateData();
  };

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();
    db.createAffiliate(newUser);
    updateData();
    setNewUser({ name: '', email: '', username: '', password: '', role: 'partner' });
    alert('Commercial Partner Provisioned Successfully.');
  };

  const handleDelete = (type: 'lead' | 'application' | 'landing_request' | 'affiliate', id: string) => {
    if(confirm('Move this entry to the Recycling Bin?')) {
      db.deleteEntry(type, id);
      updateData();
    }
  };

  const handleRestore = (type: 'lead' | 'application' | 'landing_request' | 'affiliate', id: string) => {
    db.restoreEntry(type, id);
    alert('Entry restored to active database.');
    updateData();
  };

  const handlePurge = (type: 'lead' | 'application' | 'landing_request' | 'affiliate', id: string) => {
    if(confirm('Permanent action: This will be deleted from the vault forever. Purge now?')) {
      db.purgeEntry(type, id);
      updateData();
    }
  };

  const handleUpdateStatus = (leadId: string, status: LeadStatus) => {
    db.updateLeadStatus(leadId, status);
    updateData();
  };

  const activePolicies = leads.filter(l => l.status === LeadStatus.ACTIVE || l.status === LeadStatus.BOUND).length;
  const lifetimeEarnings = user.lifetimeEarnings || 0;
  const monthlyResiduals = user.monthlyResiduals || 0;

  const isAdmin = user.role === 'admin';

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white">
      <nav className="border-b border-white/5 bg-[#171717]/80 px-6 py-4 flex justify-between items-center sticky top-0 z-50 backdrop-blur-md">
        <div className="flex items-center gap-8">
          <div className="bg-[#EAB308] text-black font-black p-2 rounded text-lg leading-none">IB</div>
          <div className="hidden md:flex items-center gap-6">
            {!isAdmin ? (
              (['overview', 'leads', 'payouts', 'tools', 'program', 'recycle_bin'] as Tab[]).map((tab) => (
                <button 
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`text-sm font-bold tracking-widest transition-colors ${activeTab === tab ? 'text-[#EAB308]' : 'text-gray-500 hover:text-white'}`}
                >
                  {tab === 'leads' ? 'Commercial Vault' : tab === 'recycle_bin' ? 'Recycling Bin' : tab === 'payouts' ? 'Earnings' : tab === 'tools' ? 'Inner Circle Tools' : tab === 'program' ? 'Commercial Info' : tab.charAt(0).toUpperCase() + tab.slice(1).replace('_', ' ')}
                </button>
              ))
            ) : (
              (['applications', 'lead_management', 'landing_requests', 'affiliate_manager', 'recycle_bin'] as Tab[]).map((tab) => (
                <button 
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`text-sm font-bold tracking-widest transition-colors ${activeTab === tab ? 'text-[#EAB308]' : 'text-gray-500 hover:text-white'}`}
                >
                  {tab === 'applications' ? 'Membership Inquiries' : tab === 'lead_management' ? 'Global Leads' : tab === 'landing_requests' ? 'Landing Requests' : tab === 'recycle_bin' ? 'Recycling Bin' : 'Commercial Member Manager'}
                </button>
              ))
            )}
          </div>
        </div>
        <div className="flex items-center gap-6">
          <div className="hidden lg:block text-right">
            <div className="text-[9px] text-gray-500 font-black tracking-widest uppercase">{isAdmin ? 'Executive Desk' : 'Commercial Partner'}</div>
            <div className="text-sm font-bold">{user.name}</div>
          </div>
          <button onClick={onLogout} className="text-[10px] bg-white/5 hover:bg-white/10 px-4 py-2 rounded-lg transition-colors border border-white/10 font-black tracking-widest">Logout</button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {!isAdmin && activeTab === 'overview' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="flex justify-between items-end">
               <div>
                  <h1 className="text-4xl font-black tracking-tighter mb-2">Commercial Dashboard</h1>
                  <p className="text-gray-500 tracking-widest text-xs font-bold uppercase">Priority B2B Performance</p>
               </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
              <StatCard label="B2B Referrals" value={leads.length} />
              <StatCard label="Contracts Bound" value={leads.filter(l => l.status === LeadStatus.BOUND || l.status === LeadStatus.ACTIVE).length} />
              <StatCard label="Commercial Portfolio" value={activePolicies} color="#3b82f6" />
              <StatCard label="Monthly Residuals" value={`$${monthlyResiduals}`} color="#EAB308" />
              <StatCard label="Lifetime B2B Dividends" value={`$${lifetimeEarnings}`} color="#22c55e" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-1 space-y-6">
                <div className="bg-[#111] border border-white/5 p-8 rounded-3xl space-y-6">
                  <h2 className="text-xl font-black tracking-tighter">B2B Verified Assets</h2>
                  <div className="space-y-4">
                    <div className="bg-black p-4 rounded-xl border border-white/10 flex flex-col items-center gap-4">
                      <div className="bg-white p-2 rounded-lg w-32 h-32 flex items-center justify-center">
                        <img src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(referralLink)}`} alt="QR Code" className="w-full h-full" />
                      </div>
                      <span className="text-[10px] font-black text-gray-500 tracking-widest uppercase">Priority Desk QR</span>
                    </div>
                    <div className="bg-[#EAB308]/5 border border-[#EAB308]/20 p-4 rounded-xl text-center">
                       <div className="text-[10px] font-black text-[#EAB308] tracking-widest uppercase mb-1">Fee Structure</div>
                       <div className="text-white font-bold text-sm">3% Grouse Premium Referral Free</div>
                    </div>
                    <Button fullWidth onClick={() => copyToClipboard()} variant={copySuccess ? 'outline' : 'primary'}>
                      {copySuccess ? 'B2B Link Copied!' : 'Copy Commercial Link'}
                    </Button>
                  </div>
                </div>

                <div className="bg-[#171717] p-8 rounded-3xl border border-white/5">
                  <h2 className="text-xl font-black tracking-tighter mb-4">Commercial Desk</h2>
                  <p className="text-sm text-gray-500 font-bold mb-6">Need specialized commercial underwriting? Contact your dedicated B2B manager.</p>
                  <a href="https://theinsuranceboss.com" target="_blank" rel="noopener noreferrer">
                    <Button variant="outline" fullWidth className="text-xs uppercase">Access Commercial Desk</Button>
                  </a>
                </div>
              </div>

              <div className="lg:col-span-2 bg-[#EAB308] text-black p-10 rounded-[40px] shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                   <h2 className="text-3xl font-black tracking-tighter mb-2">Priority B2B Intake</h2>
                   <p className="text-black/80 font-bold mb-8">Directly deposit commercial lead data into the Boss Vault for a 3% referral free.</p>
                   <div className="bg-[#0a0a0a] rounded-[32px] p-2 overflow-hidden shadow-2xl">
                    {!formSubmitted ? (
                      <MultiStepForm 
                        affiliateId={user.id} 
                        onSuccess={() => {
                          setFormSubmitted(true);
                          updateData();
                          setTimeout(() => setFormSubmitted(false), 5000);
                        }} 
                      />
                    ) : (
                      <div className="bg-[#111] p-12 text-center text-white rounded-[30px]">
                        <div className="w-20 h-20 bg-[#EAB308] rounded-full flex items-center justify-center mx-auto mb-6">
                           <svg className="w-10 h-10 text-black" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>
                        </div>
                        <h3 className="text-3xl font-black tracking-tighter mb-2">B2B Submission Verified</h3>
                        <Button onClick={() => setFormSubmitted(false)}>Submit Another Inquiry</Button>
                      </div>
                    )}
                   </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {!isAdmin && activeTab === 'payouts' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
             <div>
                <h1 className="text-4xl font-black tracking-tighter mb-2">Financial Infrastructure</h1>
                <p className="text-gray-500 tracking-widest text-xs font-bold uppercase">Commercial Dividend Management</p>
             </div>

             <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Inner Circle Statement */}
                <div className="bg-[#171717] border border-white/5 rounded-[32px] p-8 md:p-10 shadow-2xl">
                   <h2 className="text-2xl font-black tracking-tighter mb-8">Inner Circle Statement</h2>
                   <div className="space-y-6 mb-10">
                      <div className="flex justify-between items-center group">
                        <span className="text-gray-400 font-bold text-sm">Current Month Dividends</span>
                        <span className="font-black text-white text-lg">${monthlyResiduals.toFixed(0)}</span>
                      </div>
                      <div className="flex justify-between items-center group">
                        <span className="text-gray-400 font-bold text-sm">Pending Disbursements</span>
                        <span className="font-black text-white text-lg">$0.00</span>
                      </div>
                      <div className="flex justify-between items-center group">
                        <span className="text-gray-400 font-bold text-sm">Next Payout Date</span>
                        <span className="font-black text-white text-lg">June 1, 2024</span>
                      </div>
                   </div>

                   <div className="pt-8 border-t border-white/5">
                      <button className="w-full py-4 border-2 border-[#EAB308] text-[#EAB308] rounded-xl font-black text-sm tracking-widest hover:bg-[#EAB308] hover:text-black transition-all uppercase">
                        Request Priority Disbursement
                      </button>
                      <p className="mt-4 text-center text-[9px] text-gray-600 font-black tracking-[0.2em] uppercase">
                        Current Tier: 3% Grouse Premium Referral Free
                      </p>
                   </div>
                </div>

                {/* Financial Routing */}
                <div className="bg-[#171717] border border-white/5 rounded-[32px] p-8 md:p-10 shadow-2xl">
                   <h2 className="text-2xl font-black tracking-tighter mb-8">Financial Routing</h2>

                   <div className="bg-[#0d0d0d] border border-white/5 rounded-2xl p-6 mb-10 flex items-center gap-6">
                      <div className="w-14 h-14 bg-[#EAB308] rounded-xl flex items-center justify-center shrink-0">
                        <svg className="w-8 h-8 text-black" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
                        </svg>
                      </div>
                      <div>
                        <div className="text-white font-black text-lg">Priority Direct Deposit</div>
                        <div className="text-gray-600 font-mono text-xs tracking-widest">**** **** **** 8842</div>
                      </div>
                   </div>

                   <button className="w-full py-4 bg-white/5 border border-white/10 text-white rounded-xl font-black text-sm tracking-widest hover:bg-white/10 transition-all uppercase">
                      Update Routing Protocol
                   </button>
                </div>
             </div>
          </div>
        )}

        {!isAdmin && activeTab === 'tools' && (
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <ToolCard 
                title="B2B Networking Scripts" 
                desc="High-conversion commercial templates for corporate networking and premium audits." 
                onClick={() => setSelectedAsset('email')}
              />
              <ToolCard 
                title="Commercial Digital Assets" 
                desc="Exclusive pre-branded PDFs for prioritized commercial client distribution." 
                onClick={() => setSelectedAsset('flyers')}
              />
              <ToolCard 
                title="Elite Commercial SMS" 
                desc="Quick priority snippets for commercial referral distribution to business owners." 
                onClick={() => setSelectedAsset('sms')}
              />
              <ToolCard 
                title="Commercial Vault Generator" 
                desc="Request a specialized B2B landing page from our corporate producers." 
                onClick={() => setSelectedAsset('generator')}
              />
           </div>
        )}

        {!isAdmin && activeTab === 'program' && <PromotionPage standalone={false} />}
      </main>

      {/* ASSET MODAL SYSTEM */}
      {selectedAsset && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 md:p-8 animate-in fade-in duration-300">
           <div className="absolute inset-0 bg-black/90 backdrop-blur-sm" onClick={() => setSelectedAsset(null)} />
           <div className="relative w-full max-w-4xl bg-[#171717] border border-white/10 rounded-[32px] overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.8)] flex flex-col max-h-[90vh]">
              <div className="p-8 border-b border-white/5 flex justify-between items-center bg-black/40">
                 <h2 className="text-2xl font-black tracking-tighter">
                   {selectedAsset === 'email' && "Commercial Networking Scripts"}
                   {selectedAsset === 'flyers' && "Commercial B2B Digital Assets"}
                   {selectedAsset === 'sms' && "Elite B2B SMS Templates"}
                   {selectedAsset === 'generator' && "Commercial Vault Customization"}
                 </h2>
                 <button onClick={() => setSelectedAsset(null)} className="p-2 hover:bg-white/5 rounded-full transition-colors">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>

              <div className="p-8 overflow-y-auto no-scrollbar flex-grow">
                 {selectedAsset === 'email' && (
                   <div className="space-y-12">
                      <AssetItem 
                        title="Commercial Risk Audit: For B2B Clients"
                        content={`Subject: Reducing Commercial Premium Costs for [Company Name]\n\nHi [Name],\n\nI'm ${user.name}, part of the Executive Desk at The Insurance Boss. I'm reaching out because I know that risk mitigation and cost control are top priorities for your firm right now.\n\nMy team handles white-glove commercial insurance reviews for B2B accounts. We shop across 50+ national commercial carriers to find savings—often between 15-20%—without sacrificing coverage quality.\n\nWould you like to authorize a quick 5-min audit of your current General Liability or Workers' Comp declarations?\n\nBest,\n${user.name}`}
                        onCopy={(text) => copyToClipboard(text)}
                      />
                      <AssetItem 
                        title="Strategic Partnership: Logistics & Manufacturing"
                        content={`Subject: Priority Commercial Underwriting for [Partner Name]\n\nHi [Name],\n\nI'm ${user.name}, and I currently hold priority access to a senior commercial underwriting desk at The Insurance Boss.\n\nI'm reaching out because I know that for logistics and manufacturing firms, insurance binders and renewals are often a major bottleneck. We provide 24-hour turnaround on commercial quotes and direct access to specialized B2B programs.\n\nIf you have any business partners struggling with high premiums or slow renewals, you can send them directly to my priority intake vault: ${referralLink}\n\nI'll personally monitor the underwriting and provide status updates.\n\nRegards,\n${user.name}`}
                        onCopy={(text) => copyToClipboard(text)}
                      />
                   </div>
                 )}

                 {selectedAsset === 'sms' && (
                   <div className="space-y-12">
                      <AssetItem 
                        title="Commercial Intro (Professional)"
                        content={`Hey [Name]! If you need a solid commercial coverage review for your business, I have priority access to The Insurance Boss Inner Circle. They are the best in B2B risk. Check it out through my verified link: ${referralLink}`}
                        onCopy={(text) => copyToClipboard(text)}
                      />
                      <AssetItem 
                        title="Priority Commercial Referral"
                        content={`Hi [Name], for your commercial coverage needs, I'm recommending my partners at The Insurance Boss. They handle nationwide priority commercial accounts. Use my link to get moved to the top of the queue: ${referralLink}`}
                        onCopy={(text) => copyToClipboard(text)}
                      />
                   </div>
                 )}

                 {selectedAsset === 'flyers' && (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <FlyerCard title="B2B Referral One-Pager" preview="https://images.unsplash.com/photo-1586281380349-632531db7ed4?auto=format&fit=crop&q=80&w=400" />
                      <FlyerCard title="Commercial Coverage Matrix" preview="https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&q=80&w=400" />
                      <FlyerCard title="Priority WC & GL Claims" preview="https://images.unsplash.com/photo-1454165833767-02a1e74a8368?auto=format&fit=crop&q=80&w=400" />
                      <FlyerCard title="Commercial Member Onboarding" preview="https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&q=80&w=400" />
                   </div>
                 )}

                 {selectedAsset === 'generator' && (
                   <div className="max-w-xl mx-auto space-y-8 py-10">
                      <div className="text-center">
                        <h3 className="text-xl font-black mb-2">Request Commercial Vault</h3>
                        <p className="text-gray-500 text-sm font-bold">Our executive commercial producers will build a custom-niche B2B vault for your verified account.</p>
                      </div>
                      <div className="space-y-6">
                        <div className="space-y-2">
                           <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase">Target B2B Niche</label>
                           <select 
                            value={customNiche}
                            onChange={(e) => setCustomNiche(e.target.value)}
                            className="w-full bg-black border border-white/10 rounded-xl px-6 py-4 font-bold text-white appearance-none"
                           >
                              <option>Commercial Logistics & Fleet</option>
                              <option>Manufacturing & Supply Chain</option>
                              <option>Enterprise Tech & Cyber SaaS</option>
                              <option>Specialized B2B Request...</option>
                           </select>
                        </div>
                        <div className="space-y-2">
                           <label className="text-[10px] font-black text-gray-500 tracking-widest uppercase">Commercial Briefing Notes</label>
                           <textarea 
                            value={customNotes}
                            onChange={(e) => setCustomNotes(e.target.value)}
                            className="w-full bg-black border border-white/10 rounded-xl px-6 py-4 font-bold text-white h-32 no-scrollbar" 
                            placeholder="Describe your commercial audience and strategic objective..."
                           ></textarea>
                        </div>
                        <Button fullWidth onClick={handleCustomizationSubmit}>Dispatch Commercial Request</Button>
                      </div>
                   </div>
                 )}
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

// --- HELPER COMPONENTS ---

const StatCard = ({ label, value, color = 'white' }: any) => (
  <div className="bg-[#171717] p-6 rounded-2xl border border-white/5 shadow-xl">
    <div className="text-gray-500 text-[9px] font-black mb-2 tracking-widest uppercase">{label}</div>
    <div className="text-3xl font-black" style={{ color }}>{value}</div>
  </div>
);

const ToolCard = ({ title, desc, onClick }: any) => (
  <div className="bg-[#111] p-10 rounded-3xl border border-white/5 hover:border-[#EAB308]/30 transition-all flex flex-col justify-between group">
    <div>
      <h3 className="text-2xl font-black mb-4 tracking-tighter group-hover:text-[#EAB308] transition-colors">{title}</h3>
      <p className="text-gray-500 font-bold text-sm leading-relaxed mb-8">{desc}</p>
    </div>
    <Button variant="outline" onClick={onClick} className="text-xs tracking-widest">Deploy Asset</Button>
  </div>
);

const AssetItem = ({ title, content, onCopy }: { title: string, content: string, onCopy: (t: string) => void }) => {
  const [justCopied, setJustCopied] = useState(false);

  const handleCopy = () => {
    onCopy(content);
    setJustCopied(true);
    setTimeout(() => setJustCopied(false), 2000);
  };

  return (
    <div className="space-y-4">
       <div className="flex justify-between items-end">
          <h4 className="font-black text-lg tracking-tight text-[#EAB308]">{title}</h4>
          <button 
            onClick={handleCopy} 
            className={`text-[10px] font-black tracking-widest transition-colors ${justCopied ? 'text-[#EAB308]' : 'text-gray-500 hover:text-white'}`}
          >
            {justCopied ? 'Copied!' : 'Copy Text'}
          </button>
       </div>
       <div className="bg-black/50 border border-white/5 p-6 rounded-2xl font-mono text-xs text-gray-400 leading-relaxed whitespace-pre-wrap">
          {content}
       </div>
    </div>
  );
};

const FlyerCard = ({ title, preview }: { title: string, preview: string }) => (
  <div className="bg-black/50 border border-white/5 rounded-2xl overflow-hidden hover:border-[#EAB308]/50 transition-all group">
