        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Industry</h2>
            <div className="grid grid-cols-2 gap-3 max-h-[300px] overflow-y-auto pr-2 no-scrollbar">
              {industries.map(ind => (
                <button 
                  key={ind}
                  type="button"
                  onClick={() => toggleBusinessType(ind)}
                  className={`px-4 py-3 rounded-xl text-xs font-black border transition-all ${formData.businessTypes.includes(ind) ? 'bg-[#EAB308] text-black border-[#EAB308]' : 'bg-white/5 border-white/10 text-gray-500 hover:bg-white/10'}`}
                >
                  {ind}
                </button>
              ))}
            </div>
          </div>
        );
      case 5:
        return (
          <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-4xl font-black tracking-tighter mb-8 text-white">Policy Profile</h2>
            <ToggleQuestion label="Active Coverage?" value={formData.hasActiveCoverage} onChange={v => setFormData({...formData, hasActiveCoverage: v})} />
            <ToggleQuestion label="Know Monthly Premium?" value={formData.knowsPremium} onChange={v => setFormData({...formData, knowsPremium: v})} />
            <ToggleQuestion label="Declarations Ready?" value={formData.hasDeclarations} onChange={v => setFormData({...formData, hasDeclarations: v})} />
          </div>
        );
      case 7:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Authorized Contact</h2>
            <div className="space-y-4">
              <FormInput label="Decision Maker Name *" value={formData.contactName} onChange={v => setFormData({...formData, contactName: v})} placeholder="..." />
              <FormInput label="Work Email *" type="email" value={formData.email} onChange={v => setFormData({...formData, email: v})} placeholder="..." />
              <FormInput label="Direct Line *" type="tel" value={formData.phone} onChange={v => setFormData({...formData, phone: v})} placeholder="..." />
            </div>
          </div>
        );
      case 8:
        return (
          <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Final Authorization</h2>
            <div className="bg-white/5 border border-white/10 rounded-2xl p-6 space-y-4">
              <div className="flex justify-between border-b border-white/5 pb-2">
                <span className="text-gray-400 text-xs font-bold tracking-widest uppercase">Entity</span>
                <span className="font-bold text-white uppercase">{formData.businessName}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2">
                <span className="text-gray-400 text-xs font-bold tracking-widest uppercase">Authorized Rep</span>
                <span className="font-bold text-white">{formData.contactName}</span>
              </div>
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="w-full">
      <div className="mb-4 space-y-2">
        <div className="flex justify-between items-end">
          <span className="text-[#EAB308] text-[9px] font-black tracking-[0.2em] uppercase">Step {step} of {totalSteps}</span>
          <span className="text-white text-xl font-black">{progress}%</span>
        </div>
        <div className="h-1 bg-white/10 rounded-full overflow-hidden">
          <div className="h-full bg-[#EAB308] transition-all duration-500 shadow-[0_0_10px_rgba(234,179,8,0.5)]" style={{ width: `${progress}%` }} />
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-[#111] border border-white/10 rounded-[32px] p-8 shadow-2xl min-h-[500px] flex flex-col">
        <div className="flex-grow">
          {renderStep()}
        </div>
        <div className="mt-8 flex gap-4">
          {step > 1 && (
            <button type="button" onClick={prevStep} className="px-6 py-4 rounded-2xl bg-white/5 border border-white/10 font-black text-xs tracking-widest text-gray-400 hover:bg-white/10 transition-all uppercase">Back</button>
          )}
          {step < totalSteps ? (
            <button type="button" onClick={() => {
               if (step === 3) setStep(5);
               else if (step === 5) setStep(7);
               else if (step === 7) setStep(8);
               else nextStep();
            }} className="flex-1 px-6 py-4 rounded-2xl bg-[#EAB308] text-black font-black text-xs tracking-[0.2em] hover:scale-[1.01] active:scale-95 transition-all uppercase">Continue</button>
          ) : (
            <button type="submit" className="flex-1 px-6 py-4 rounded-2xl bg-[#EAB308] text-black font-black text-xs tracking-[0.2em] hover:scale-[1.01] active:scale-95 transition-all uppercase">Initialize Desk</button>
          )}
        </div>
      </form>
    </div>
  );
};

export const FormInput = ({ label, ...props }: any) => (
  <div className="space-y-1">
    <label className="block text-[9px] font-black text-[#EAB308] tracking-widest uppercase">{label}</label>
    <input 
      {...props}
      className="w-full bg-black border border-white/5 rounded-xl px-4 py-3 focus:outline-none focus:border-[#EAB308] transition-all font-bold text-white placeholder:text-gray-500"
      onChange={e => props.onChange?.(e.target.value)}
    />
  </div>
);

export const ToggleQuestion = ({ label, value, onChange }: any) => (
  <div className="bg-black/40 border border-white/5 rounded-xl p-4 flex justify-between items-center gap-4 hover:border-white/20 transition-all">
    <span className="font-black text-gray-200 text-[10px] tracking-wider uppercase">{label}</span>
    <div className="flex bg-black p-1 rounded-lg">
      <button type="button" onClick={() => onChange(true)} className={`px-4 py-1 rounded text-[10px] font-black transition-all ${value ? 'bg-[#EAB308] text-black shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>Yes</button>
      <button type="button" onClick={() => onChange(false)} className={`px-4 py-1 rounded text-[10px] font-black transition-all ${!value ? 'bg-[#EAB308] text-black shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>No</button>
    </div>
  </div>
);

