// Custom Dropdown Component to fix the background issue
const StatusDropdown = ({ value, onChange }: { value: LeadStatus, onChange: (s: LeadStatus) => void }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getStatusStyles = (status: LeadStatus) => {
    switch(status) {
      case LeadStatus.RECEIVED: return 'border-blue-500/50 text-blue-500 bg-blue-500/10 hover:border-blue-500';
      case LeadStatus.IN_PROGRESS: return 'border-amber-500/50 text-amber-500 bg-amber-500/10 hover:border-amber-500';
      case LeadStatus.QUOTED: return 'border-gray-500/50 text-gray-400 bg-gray-500/10 hover:border-gray-400';
      case LeadStatus.BOUNCED: return 'border-emerald-500/50 text-emerald-500 bg-emerald-500/10 hover:border-emerald-500';
      case LeadStatus.REJECTED: return 'border-red-500/50 text-red-500 bg-red-500/10 hover:border-red-500';
      default: return 'border-white/10 text-white bg-white/5';
    }
  };

  return (
    <div className="relative inline-block" ref={containerRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center gap-3 px-4 py-1.5 rounded-full border text-[10px] font-black uppercase tracking-widest transition-all outline-none ${getStatusStyles(value)}`}
      >
        {value}
        <svg className={`w-3 h-3 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {isOpen && (
        <div className="absolute left-0 mt-2 w-48 bg-[#171717] border border-white/10 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] z-[100] overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 backdrop-blur-xl">
          {(Object.values(LeadStatus) as LeadStatus[]).map((status) => (
            <div
              key={status}
              onClick={() => {
                onChange(status);
                setIsOpen(false);
              }}
              className={`px-5 py-3.5 text-[10px] font-black uppercase tracking-widest cursor-pointer hover:bg-white/5 transition-colors border-b border-white/5 last:border-none ${value === status ? 'text-[#EAB308] bg-white/[0.02]' : 'text-gray-400'}`}
            >
              {status}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

