export const MultiStepForm: React.FC<{ affiliateId: string; onSuccess: () => void }> = ({ affiliateId, onSuccess }) => {
  const [step, setStep] = useState(1);
  const totalSteps = 8;
  const progress = Math.round((step / totalSteps) * 100);

  const [formData, setFormData] = useState({
    businessName: '',
    dba: '',
    fein: '',
    yearsInBusiness: '',
    address: '',
    address2: '',
    city: '',
    state: '',
    zip: '',
    country: 'United States',
    businessTypes: [] as string[],
    hasActiveCoverage: false,
    knowsPremium: false,
    hasDeclarations: false,
    contactName: '',
    email: '',
    phone: '',
  });

  const nextStep = () => setStep(s => Math.min(s + 1, totalSteps));
  const prevStep = () => setStep(s => Math.max(s - 1, 1));

  const toggleBusinessType = (type: string) => {
    setFormData(prev => ({
      ...prev,
      businessTypes: prev.businessTypes.includes(type)
        ? prev.businessTypes.filter(t => t !== type)
        : [...prev.businessTypes, type]
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    db.addLead(affiliateId, formData.contactName, formData.email, formData.phone, {
      businessName: formData.businessName,
      dba: formData.dba,
      fein: formData.fein,
      yearsInBusiness: formData.yearsInBusiness,
      address: formData.address,
      city: formData.city,
      state: formData.state,
      zipCode: formData.zip,
      businessTypes: formData.businessTypes,
      hasActiveCoverage: formData.hasActiveCoverage,
      knowsPremium: formData.knowsPremium,
      hasDeclarations: formData.hasDeclarations,
    });
    onSuccess();
  };

  const renderStep = () => {
    switch(step) {
      case 1:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Company Identity</h2>
            <div className="space-y-4">
              <FormInput label="Business Legal Name *" value={formData.businessName} onChange={v => setFormData({...formData, businessName: v})} placeholder="Legal Entity Name" />
              <FormInput label="DBA (Doing Business As)" value={formData.dba} onChange={v => setFormData({...formData, dba: v})} placeholder="Trade Name" />
              <div className="grid grid-cols-2 gap-4">
                <FormInput label="Federal EIN *" value={formData.fein} onChange={v => setFormData({...formData, fein: v})} placeholder="XX-XXXXXXX" />
                <FormInput label="Years Active *" value={formData.yearsInBusiness} onChange={v => setFormData({...formData, yearsInBusiness: v})} placeholder="Age of Business" />
              </div>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Headquarters</h2>
            <div className="space-y-4">
              <FormInput label="HQ Address *" value={formData.address} onChange={v => setFormData({...formData, address: v})} placeholder="..." />
              <FormInput label="City *" value={formData.city} onChange={v => setFormData({...formData, city: v})} placeholder="..." />
              <div className="grid grid-cols-2 gap-4">
                <FormInput label="State *" value={formData.state} onChange={v => setFormData({...formData, state: v})} placeholder="..." />
                <FormInput label="Zip Code *" value={formData.zip} onChange={v => setFormData({...formData, zip: v})} placeholder="..." />
              </div>
            </div>
          </div>
        );
      case 3:
        const industries = ["Logistics & Fleet", "Tech & Cyber", "Manufacturing", "Medical & Pharma", "Professional Services", "Real Estate Dev", "Hospitality", "Wholesale", "Agriculture", "Construction", "Auto Dealership", "Food & Beverage", "Retail", "Other"];
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-3xl font-black tracking-tighter mb-8 text-white">Industry</h2>
            <div className="grid grid-cols-2 gap-3 max-h-[300px] overflow-y-auto pr-2 no-scrollbar">
              {industries.map(ind => (
