      <button onClick={() => onChange(false)} className={`px-4 py-1.5 rounded-md text-[10px] font-black transition-all ${!value ? 'bg-[#EAB308] text-black shadow-lg' : 'text-gray-600 hover:text-gray-400'}`}>No</button>
