  const totalSteps = 8;
  const progress = step === 1 ? 13 : step === 2 ? 25 : step === 3 ? 38 : step === 5 ? 63 : step === 7 ? 88 : 100;

  const [formData, setFormData] = useState({
    businessName: '', dba: '', fein: '', yearsInBusiness: '',
